const originalBody=bodyFor, originalOpen=openModal;
const rupiah=n=>'Rp'+Math.floor(n||0).toLocaleString('id-ID');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let catalogue=[], state={}; fetch('catalog.json').then(r=>r.json()).then(d=>catalogue=d);
const subtitles2={'Asisten TikTok Ads via MCP':'Akses data iklan melalui asisten AI.','TikTok Kolaborasi Plus':'Cari dan kelola kerja sama dengan kreator.','TikTok Market Scope':'Pahami insight pasar dan cara menggunakannya.','TikTok Content Suite':'Paket video Buzzo sesuai komitmen belanja iklan.','TikTok Creator Marketing':'Beli konten kreator dengan minimum organic views.','TikTok Commercial Partnership Solutions':'Video kreator untuk mendukung kampanye iklan.'};Object.assign(subtitles,subtitles2);
const card=(title,body)=>`<div class="modal-card"><h3>${title}</h3>${body}</div>`;
const chip=arr=>`<div class="chips">${arr.map(x=>`<span>${x}</span>`).join('')}</div>`;
function collab(){let goals=state.goals||{videos:2}, budget=state.budget??5000000, slots=state.slots??5, page=state.page??0; const parts=Array.from({length:24},(_,i)=>({id:i+1,name:`Kreator ${String(i+1).padStart(2,'0')}`,videos:[6,3,4,1,5,2,0,3][i%8],views:[88000,46000,120000,9500,62000,28000,17000,46000][i%8],gmv:[8200000,4100000,6600000,750000,5400000,2400000,900000,4100000][i%8]}));let active=Object.entries(goals).filter(([,v])=>v!==undefined);let valid=Number.isSafeInteger(budget)&&budget>0&&Number.isSafeInteger(slots)&&slots>=1&&slots<=budget&&active.length&&active.every(([,v])=>v>0);let ranked=valid?parts.map(p=>({...p,qualified:active.every(([k,v])=>p[k]>=v),score:100*active.reduce((a,[k,v])=>a+p[k]/v,0)/active.length})).sort((a,b)=>Number(b.qualified)-Number(a.qualified)||b.score-a.score||b.gmv-a.gmv||b.views-a.views||b.videos-a.videos||a.id-b.id):[];let qualified=ranked.filter(p=>p.qualified).length,winners=Math.min(qualified,slots),reward=Math.floor(budget/slots),paid=winners*reward;let fields=[['videos','Video',2],['views','Organic views',10000],['gmv','GMV',1000000]].map(([key,label,def])=>`<div class="goal-row"><label><input type="checkbox" data-goal-toggle="${key}" ${goals[key]!==undefined?'checked':''}> ${label}</label>${goals[key]!==undefined?`<label>Target ${label}<input type="number" min="1" data-goal="${key}" value="${goals[key]}"></label>`:'<small>Tidak dipakai</small>'}</div>`).join('');let result=valid?`<div class="stat-grid">${[['Hadiah per slot',rupiah(reward)],['Pemenang / slot',`${winners} / ${slots}`],['Kreator lolos',qualified],['Total hadiah',rupiah(paid)],['Budget tersisa',rupiah(budget-paid)],['Goal aktif',active.length]].map(([a,b])=>`<div><small>${a}</small><strong>${b}</strong></div>`).join('')}</div><p>Data kreator sintetis tetap. Skor = rata-rata persentase pencapaian, tanpa batas 100%. Slot kosong tidak dibayar. Tidak ada pembayaran pada demo.</p>`:'<p>Masukkan budget, slot, dan setidaknya satu goal yang valid.</p>';let list=ranked.slice(page*5,page*5+5).map((p,i)=>`<div class="modal-card"><strong>${page*5+i+1}. ${p.name}</strong> · ${p.qualified?(page*5+i<slots?'Lolos · pemenang':'Lolos · di luar kuota'):'Belum lolos'}<div class="video-placeholders"><span>▶ Video 1</span><span>▶ Video 2</span><span>▶ Video 3</span></div><p>Video ${p.videos}${goals.videos?` / ${goals.videos} · ${Math.round(p.videos/goals.videos*100)}%`:' · tanpa target'}　Organic views ${p.views.toLocaleString('id-ID')}　GMV ${rupiah(p.gmv)}</p><strong>Skor ${Math.round(p.score)}% · Hadiah ${rupiah(p.qualified&&page*5+i<slots?reward:0)}</strong></div>`).join('');return `<p>Brand dapat mencari, mengajak, dan mengelola kreator affiliate dengan lebih praktis.</p>${chip(['Budget kreator','Goal dan reward','Sistem mengelola'])}${card('DEMO · GOAL & REWARD',`<div class="stat-grid"><label>Budget total kreator<input type="number" min="0" step="100000" data-collab="budget" value="${budget}"><input type="range" min="100000" max="${Math.max(20000000,budget)}" step="100000" data-collab="budget" value="${budget}"></label><label>Jumlah slot pemenang<input type="number" min="1" max="100" data-collab="slots" value="${slots}"><input type="range" min="1" max="${Math.max(30,slots)}" data-collab="slots" value="${slots}"></label></div><h3>Goal per kreator · semua goal aktif wajib tercapai</h3>${fields}`)}${card('Hasil simulasi reward',result)}<h3>Leaderboard kreator</h3>${list}<div class="flow-actions"><button class="action" data-collab-page="${page-1}" ${page===0?'disabled':''}>Sebelumnya</button><span>${page+1} / 5</span><button class="action" data-collab-page="${page+1}" ${page>=4?'disabled':''}>Berikutnya</button></div>`}
function getAgency(){return catalogue.find(x=>x.id===(state.agency||'hanindo'))||catalogue[0]}
function interpolate(v,points){let prev=[0,0];for(const p of points){if(v<=p[0])return prev[1]+(v-prev[0])*(p[1]-prev[1])/(p[0]-prev[0]);prev=p}let end=points.at(-1),start=points.at(-2);return end[1]+(v-end[0])*(end[1]-start[1])/(end[0]-start[0])}
function suiteQuota(n){return {videos:n/1000000,creators:Math.min(n/1000000,Math.max(1,Math.floor(interpolate(n,[[17868000,3],[53604000,5],[107208000,10]])))),refs:Math.max(1,Math.floor(interpolate(n,[[17868000,4],[53604000,6],[107208000,8]])))}}
function creative(){let mode=state.mode, step=state.step||0, ag=getAgency();if(!ag)return '<p>Memuat katalog…</p>';let suite=mode==='suite', creator=mode==='creator', cps=mode==='cps';let n=state.budget??(suite?30000000:1000000),q=suite?suiteQuota(n):{creators:Math.floor(n/500000),views:Math.floor(n/500000)*28000};let pack=ag.commitments.find(x=>x.id===state.package), max=creator?q.creators:suite?q.creators:pack?.maxTalentCount||0, min=cps?pack?.minTalentCount||1:1;let maxrefs=creator?undefined:suite?q.refs:pack?.maxReferenceCount??pack?.totalVideoCount??0;let selected=state.selected||[],refs=state.refs||[],brief=state.brief||'';let nav=['Budget / paket',cps?'Persona':'Kreator','Referensi & brief','Ringkasan'].map((x,i)=>`<button class="action ${step===i?'active':''}" data-flow-step="${i}" ${i>step?'disabled':''}>${x}</button>`).join('');let body='';if(step===0){if(cps&&!state.agency)body=`<h3>Pilih agency terlebih dahulu</h3><p>Setiap agency memiliki paket dan talent yang berbeda. Pilih agency untuk melihat paket yang tersedia.</p>${catalogue.map(a=>`<div class="modal-card"><h3>${esc(a.name)}</h3><p>${esc(a.description)}</p><p>${a.creators.length} talent tersedia</p><button class="action" data-agency="${a.id}">Lihat paket agency</button></div>`).join('')}`;else if(cps)body=`<button class="action" data-agency="">← Ganti agency</button><h3>${esc(ag.name)} · Pilih paket</h3>${ag.commitments.map(p=>`<div class="modal-card"><h3>${esc(p.packageLabel)}</h3><p>Belanja iklan ${esc(p.last30DaysAdSpendLabel)} · ${p.totalVideoCount} video · ${p.minTalentCount}–${p.maxTalentCount} talent</p><button class="action ${state.package===p.id?'active':''}" data-package="${p.id}">${state.package===p.id?'Dipilih':'Pilih paket'}</button></div>`).join('')}`;else body=`<h3>${suite?'Tentukan budget iklanmu':'Estimasi hasil kampanye'}</h3><p>${suite?'Bandingkan syarat belanja iklan dan konten yang akan kamu terima.':'Tentukan budget belanja kreator. Budget iklan terpisah.'}</p><label>${suite?'Budget belanja iklan':'Budget belanja kreator'}<input type="number" min="0" step="${suite?1000000:500000}" data-creative-budget value="${n}"></label><input type="range" min="${suite?1000000:500000}" max="${Math.max(n,suite?150000000:10000000)}" step="${suite?1000000:500000}" data-creative-budget value="${n}">${suite?`<p><strong>${q.videos} short video</strong> untuk 30 hari</p><p>Konten yang kamu dapatkan: ${q.videos} short video · Maks. ${q.creators} kreator · ${q.refs} referensi</p><p>Rp1 juta komitmen belanja iklan 30 hari = 1 short video.</p>`:`<p><strong>${q.views.toLocaleString('id-ID')} estimasi organic views</strong></p><p>Maks. kreator ${q.creators} · Budget terpakai ${rupiah(q.creators*500000)} · Budget tersisa ${rupiah(n%500000)}</p><p>Estimasi paket: Rp500.000/kreator · 28.000 organic views/kreator. Budget iklan terpisah.</p>`}`}
 if(step===1){body=`<h3>Pilih ${cps?'persona':suite?'Account':'kreator'}</h3><p>${selected.length} dari maksimal ${max} dipilih${cps?` · minimal ${min}`:''}</p>${ag.creators.map(c=>`<div class="modal-card"><h3>${esc(cps&&ag.id==='hanindo'?c.focusLabel||c.name:c.handle?'@'+c.handle:c.name)}</h3><p>${esc(c.description||c.focusLabel||'')}</p><button class="action ${selected.includes(c.id)?'active':''}" data-select-creator="${c.id}" ${c.status!=='available'||(!selected.includes(c.id)&&selected.length>=max)?'disabled':''}>${c.status!=='available'?'Terkunci':selected.includes(c.id)?'Dipilih':'Pilih '+(suite?'Account':cps?'persona':'kreator')}</button> ${(c.videoUrls||[c.bestVideoUrl].filter(Boolean)).slice(0,3).map((url,i)=>`<a href="${esc(url)}" target="_blank" rel="noopener">Contoh video ${i+1} ↗</a>`).join(' · ')}</div>`).join('')}`}
 if(step===2){let group=state.group||'content_type',filter=state.filter||'all',vid=ag.videoLibrary.filter(v=>v.group===group&&(filter==='all'||v.categoryId===filter)),page=state.videoPage||0;body=`<h3>Referensi & brief</h3><label>Brief ${creator?'(wajib)':'(opsional)'}<textarea maxlength="2000" data-brief>${esc(brief)}</textarea></label><p>${brief.length}/2000 karakter</p><div class="chips"><button class="action" data-group="content_type">Format konten</button><button class="action" data-group="industry">Industri</button></div><div class="chips"><button class="action" data-filter="all">Semua</button>${ag.videoCategories.filter(c=>c.group===group).map(c=>`<button class="action" data-filter="${c.id}">${esc(c.label)}</button>`).join('')}</div><p>${refs.length}${maxrefs!==undefined?'/'+maxrefs:''} referensi dipilih · ${vid.length} contoh pada filter ini</p>${vid.slice(page*6,page*6+6).map(v=>`<div class="modal-card"><strong>${esc(v.title)}</strong><p>@${esc(v.creatorHandle||'')} · ${esc(v.categoryLabel)}</p><a target="_blank" rel="noopener" href="${esc(v.url)}">Lihat video ↗</a> <button class="action ${refs.includes(v.id)?'active':''}" data-ref="${v.id}" ${!refs.includes(v.id)&&maxrefs!==undefined&&refs.length>=maxrefs?'disabled':''}>${refs.includes(v.id)?'Dipilih':'Pilih referensi'}</button></div>`).join('')}<div class="flow-actions"><button class="action" data-video-page="${page-1}" ${page<=0?'disabled':''}>Sebelumnya</button><span>${page+1} / ${Math.max(1,Math.ceil(vid.length/6))}</span><button class="action" data-video-page="${page+1}" ${(page+1)*6>=vid.length?'disabled':''}>Berikutnya</button></div>`}
 if(step===3)body=`<h3>Ringkasan pilihan</h3><p>Agency: ${esc(ag.name)}</p><p>${cps?'Paket: '+esc(pack?.packageLabel):'Budget: '+rupiah(n)}</p><p>${selected.length} ${cps?'persona':'kreator'} dipilih</p><ul>${selected.map(id=>`<li>${esc(ag.creators.find(c=>c.id===id)?.name||id)}</li>`).join('')}</ul><p>${refs.length} referensi dipilih</p><p>Brief: ${esc(brief)||'Belum diisi'}</p><p>Login diperlukan untuk melanjutkan. Pilihan hanya ada selama sesi ini.</p>`;
 let can=step===0?(cps?!!pack:suite?n>=1000000&&n%1000000===0:q.creators>0):step===1?selected.length>=min&&selected.length<=max:step===2?!creator||brief.trim().length>0:true;
 return `<div class="chips">${nav}</div>${card('Langkah '+(step+1)+' dari 4',body)}<div class="flow-actions">${step?'<button class="action" data-flow-back>Kembali</button>':''}${step<3?`<button class="cta" data-flow-next ${can?'':'disabled'}>Lanjut</button>`:'<button class="cta" data-register>Mulai gratis</button>'}</div>`}
function market(){let tab=state.market||'Audience Funnel';let data={'Audience Funnel':'<h3>Brand contoh</h3><p>Awareness 84.000 · 80,8%</p><p>Consideration 16.000 · 15,4%</p><p>Conversion 4.000 · 3,8%</p><h3>Benchmark contoh</h3><p>Awareness 240.000 · 75,9%</p><p>Consideration 60.000 · 19,0%</p><p>Conversion 16.000 · 5,1%</p>','Contribution Analysis':'<h3>Contribution Analysis</h3><p>Contoh kontribusi channel terhadap audiens di setiap tahap.</p>','Audience Profile':'<h3>Audience Profile</h3><p>Contoh profil audiens berdasarkan kelompok demografi.</p>','Audience Transition':'<h3>Audience Transition</h3><p>Contoh pergerakan audiens dari awareness ke conversion.</p>'};return `<p>Brand mendapat insight pasar serta konsultasi untuk membantu memahami dan memanfaatkannya.</p>${chip(['Baca funnel','Temukan channel','Alokasikan budget'])}${card('DEMO · MARKET SCOPE',`<div class="chips">${Object.keys(data).map(x=>`<button class="action ${tab===x?'active':''}" data-market="${x}">${x}</button>`).join('')}</div>${data[tab]}`)}`}
function report(){let tabs=['Summary','Commerce','Advertising Performance','Advertising Branding','Creator Affiliate','Creator Branded Content','Social Media Video','Social Media Live','Appendix'],t=state.report||'Summary';let descriptions={'Summary':['Shop GMV','Rp102,9 jt','Items sold','868'],'Commerce':['Shop GMV','Rp102,9 jt','Items sold','868'],'Advertising Performance':['Ad spend','Rp16,1 jt','Ad GMV','Rp85,75 jt'],'Advertising Branding':['Impressions','402.500','Clicks','17.500'],'Creator Affiliate':['Affiliate GMV','Rp41,16 jt','Kreator','7'],'Creator Branded Content':['Konten kreator','7','Views','147.000'],'Social Media Video':['Video','7','Views','147.000'],'Social Media Live':['Social Media GMV','Rp61,74 jt','Periode','7–13 Sep 2026'],'Appendix':['Sumber data','Data sintetis','Periode','7–13 Sep 2026']},m=descriptions[t];return `<p>Rekomendasi berbasis data dapat membantu brand agar dapat mengoptimalkan iklan.</p>${card('Brand Contoh JJTA',`<p>Data contoh · 7 Sep 2026 – 13 Sep 2026</p><div class="chips">${tabs.map(x=>`<button class="action ${x===t?'active':''}" data-report="${x}">${x}</button>`).join('')}</div><details><summary>Partial data · review source coverage</summary><p>Data contoh untuk demonstrasi dashboard.</p></details><h3>${esc(t)} · Overview</h3><div class="stat-grid"><div><small>${m[0]}</small><strong>${m[1]}</strong></div><div><small>${m[2]}</small><strong>${m[3]}</strong></div></div><details><summary>Sources and comparisons</summary><p>Data contoh · 14/9/2026, 09.00 WIB</p></details><h3>Trend</h3><div class="graph"><svg viewBox="0 0 400 100" preserveAspectRatio="none"><path d="M0 92 L65 80 L130 70 L195 57 L260 43 L325 25 L400 8" fill="none" stroke="#84e4ee" stroke-width="3"/></svg></div><p>Data diambil · 14/9/2026, 09.00 WIB</p>${t==='Commerce'?'<h3>GMV mix by account & channel</h3><p>Affiliate · 40% · Rp41,16 jt</p><p>Social Media residual · 60% · Rp61,74 jt</p>':''}<p class="muted">Contoh report sintetis; dashboard lengkap dan sumber data asli belum terhubung.</p>`)} `}
function symphony(){let submitted=state.sent,approved=state.approved;return `<p>Perangkat kreatif AI dari TikTok membantu brand memproduksi konten dalam skala besar.</p>${chip(['Foto dan brief','Review video','Posting dan iklankan'])}${card('Symphony Agent',`<p>Demo lokal · data dan proses contoh</p><div class="chips"><button class="action" data-demo-play>${state.playing?'Jeda demo chat':'Putar demo chat'}</button><button class="action" data-demo-reset>Ulangi demo chat</button></div><p>Assistant: Pilih foto produk contoh dan kirim arahan videomu. Gambar kopi dapat ditambahkan sebagai referensi gaya.</p>${!submitted?`<label><input type="checkbox" data-photo checked> Foto produk Veraldo</label><br><label><input type="checkbox" data-reference> Referensi gaya (opsional)</label><label>Brief video<textarea data-symphony-brief>Buat video review produk Veraldo dengan suasana santai di mall, perlihatkan detail produk dan tutup dengan ajakan mencoba.</textarea></label><button class="action" data-demo-submit>Kirim brief demo</button>`:`<div class="modal-card"><strong>Kamu</strong><p>${esc(state.symphonyBrief)}</p></div><div class="modal-card"><strong>Symphony Agent</strong><p>Menyiapkan konsep dan draft video berdasarkan foto produk dan brief.</p><p>Contoh draft video · simulasi lokal</p>${approved?'<p>Video contoh disetujui untuk digunakan di sosial media dan TikTok Ads.</p>':'<button class="action" data-demo-approve>Setujui video</button>'}</div>`}`)}`}
function assistantDemo(){return `<p>Koneksi MCP membantu brand memahami performa iklan dan menemukan peluang optimasi melalui data TikTok Ads.</p>${chip(['1 · Hubungkan TikTok','2 · Hubungkan AI','3 · Mulai chat'])}${card('ChatGPT · TikTok Ads',`<p>Demo lokal · data dan proses contoh</p><button class="action" data-assist-play>${state.playing?'Jeda demo chat':'Putar demo chat'}</button> <button class="action" data-assist-reset>Ulangi demo chat</button><p>Kamu: Bagaimana performa Consideration Ads dan GMV Max minggu ini?</p>${state.playing?'<p>Asisten: Saya akan memeriksa data performa dan mencari peluang optimasi berdasarkan data contoh.</p>':''}`)}`}
bodyFor=function(id){if(id==='TikTok Kolaborasi Plus')return collab();if(id==='TikTok Market Scope')return market();if(id==='Rekomendasi')return report();if(id==='TikTok Symphony')return symphony();if(id==='Asisten TikTok Ads via MCP')return assistantDemo();if(['TikTok Content Suite','TikTok Creator Marketing','TikTok Commercial Partnership Solutions'].includes(id))return creative();return originalBody(id)};
openModal=function(id){state={id};if(id==='TikTok Content Suite')state.mode='suite';if(id==='TikTok Creator Marketing')state.mode='creator';if(id==='TikTok Commercial Partnership Solutions')state.mode='cps';if(id==='TikTok Kolaborasi Plus')state.goals={videos:2};originalOpen(id);if(['suite','creator','cps'].includes(state.mode)&&!catalogue.length)fetch('catalog.json').then(r=>r.json()).then(d=>{catalogue=d;renderExperience()})};
function renderExperience(){let target=document.querySelector('#modal-body');if(target&&state.id)target.innerHTML=benefitAccess(state.id)+bodyFor(state.id)}
function showAuth(type){closeModal();const auth=document.querySelector('#auth-screen');auth.hidden=false;document.body.classList.add('auth-open');state.auth=type;state.regStep=1;renderAuth();window.scrollTo(0,0)}
function renderAuth(){let auth=document.querySelector('#auth-screen'),isLogin=state.auth==='login',step=state.regStep||1;let info=isLogin?`<small>PORTAL SELLER JJTA</small><h1>Selamat datang kembali di Jurus Jitu TikTok Ads</h1><p>Masuk untuk melanjutkan checklist program dan mengakses manfaat yang sudah terbuka untuk akunmu.</p><p>✧ Strategi iklan yang lebih terarah<br>✧ Community support bersama seller<br>✧ Data tersimpan dengan aman</p>`:`<small>CARA BERGABUNG · 3 LANGKAH</small><h1>Registrasi, hubungkan akun, konfirmasi.</h1><p>Ikuti tiga langkah ini supaya proses bergabung ke program JJTA berjalan lancar.</p><div class="auth-step"><b>01 · Registrasi akun</b><p>Masukkan kode undangan, lalu isi nama, nomor WhatsApp, email, dan password.</p></div><div class="auth-step"><b>02 · Hubungkan akun (binding)</b><p>Isi Advertiser ID, Shop Code, link TikTok Shop, dan nama toko supaya akun bisa dicocokkan.</p></div><div class="auth-step"><b>03 · Konfirmasi akses</b><p>Setujui permintaan akses data performa agar verifikasi dan aktivasi program bisa diproses.</p></div><p>SIAPKAN SEBELUM MULAI<br>Kode undangan JJTA · Nama lengkap · Nama toko · Link TikTok Shop · Advertiser ID · Shop Code · Email & password · Nomor WhatsApp</p>`;let form=isLogin?`<h2>Masuk ke akun</h2><p>Gunakan email dan password yang sudah kamu daftarkan.</p><form id="auth-login"><label>Email<input type="email" required autocomplete="off"></label><label>Kata sandi<input type="password" required autocomplete="off"></label><a href="#" data-forgot>Lupa kata sandi?</a><p><label><input type="checkbox" style="width:auto"> Ingat saya</label></p><button class="cta">Masuk</button><p class="auth-notice" role="status"></p></form>`:step===1?`<h2>Kode undangan</h2><p>Masukkan kode undangan dari event atau tim JJTA untuk melanjutkan.</p><form id="reg-code"><label>Kode undangan<input name="invite" required autocomplete="off"></label><button class="cta">Validasi & lanjut</button><p class="auth-notice">Mode tampilan: kode belum terhubung ke server dan tidak akan divalidasi.</p></form>`:step===2?`<h2>Data bisnis dan toko</h2><p>Data ini membantu tim membaca kondisi iklan dan toko dengan tepat.</p><form id="reg-shop"><label>Advertiser ID<input required placeholder="7656489039265012345"></label><label>Nama Toko TikTok Shop<input required placeholder="Masukkan nama toko Anda"></label><label>Link TikTok Shop<input type="url" required placeholder="https://www.tiktok.com/..."></label><label>Shop Code<input required placeholder="IDLCRFHLWN3 (bukan Shop ID angka panjang)"></label><label>Setelah mengikuti seluruh rangkaian JJTA, apakah kamu tertarik menggunakan layanan berbayar Buzzo?<select required><option value="">Pilih jawaban</option><option>Ya</option><option>Belum yakin</option><option>Tidak</option></select></label><div class="flow-actions"><button type="button" class="action" data-reg-back>Kembali</button><button class="cta">Lanjut ke data akun</button></div></form>`:`<h2>Data akun</h2><p>Gunakan email dan password ini untuk masuk ke portal JJTA.</p><form id="reg-account"><label>Nama lengkap<input required></label><label>Nomor WhatsApp<input type="tel" required></label><label>Email<input type="email" required autocomplete="off"></label><label>Kata sandi<input type="password" minlength="8" maxlength="15" required autocomplete="new-password"></label><label>Konfirmasi kata sandi<input type="password" minlength="8" maxlength="15" required autocomplete="new-password"></label><div class="flow-actions"><button type="button" class="action" data-reg-back>Kembali</button><button class="cta">Kirim pendaftaran</button></div><p class="auth-notice" role="status"></p></form>`;auth.innerHTML=`<header><button class="action" data-auth-close>← Kembali ke landing page</button><div class="logo"><img src="assets/jjta-logo-official.png" alt="Jurus Jitu TikTok Ads"></div><span>${isLogin?'LOGIN':'REGISTRATION'}</span></header><div class="auth-grid"><section>${info}</section><section class="auth-form">${!isLogin?`<nav class="auth-progress">${['KODE','TOKO','AKUN'].map((x,i)=>`<span class="${step===i+1?'current':''}">${i+1} ${x}</span>`).join('')}</nav>`:''}${form}<p class="auth-notice">Tampilan percobaan · Data belum disimpan dan login belum terhubung.</p></section></div>`}
document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;const ds=el.dataset;
 if(el.matches('.hero .cta,.program-cta,.modal > .cta')||ds.register!==undefined){e.preventDefault();e.stopImmediatePropagation();showAuth('register');return}if(el.matches('.hero .login-link')){e.preventDefault();e.stopImmediatePropagation();showAuth('login');return}
 if(ds.authClose!==undefined){document.querySelector('#auth-screen').hidden=true;document.body.classList.remove('auth-open');state={};return}if(ds.forgot!==undefined){e.preventDefault();el.closest('form').querySelector('.auth-notice').textContent='Pemulihan kata sandi belum terhubung.';return}if(ds.regBack!==undefined){state.regStep--;renderAuth();return}
 if(ds.material){e.preventDefault();e.stopImmediatePropagation();let title=ds.material;try{let data=await fetch('materials.json').then(r=>r.json()),p=data[title==='TikTok One: Tips & Trik untuk Seller TikTok Ads'?'Panduan Memilih Produk TikTok One':title]?.page;if(!p)throw Error('not found');document.querySelector('#modal-title').textContent=title;document.querySelector('#modal-sub').textContent='JJTA Learning Center content';let sections=(p.sections||[]).map(s=>`<p><strong>${esc(s.title||'')}</strong> ${esc(s.body||'')} ${esc(s.description||'')}</p>`).join('');document.querySelector('#modal-body').innerHTML=`<p>Pratinjau materi</p><div class="lesson-slide"><small>BUZZO / JJTA LEARNING CENTER</small><h2>${esc(p.title).replace(/\n/g,'<br>')}</h2><p>${esc(p.body||'')}</p>${(p.bullets||[]).map(x=>`<p>${esc(x)}</p>`).join('')}${sections}<small>JURUS JITU TIKTOK ADS</small></div><p>Slide 1 / 1</p><button class="action" disabled>Sebelumnya</button> <button class="action" disabled>Berikutnya</button> <label><input type="checkbox" style="width:auto" data-original-size> Ukuran asli</label> <button class="action" data-lesson-full>Tampilan penuh</button> <button class="action" data-lesson-back>Kembali ke konten</button>`}catch{document.querySelector('#modal-body').innerHTML='<p>Materi belum dapat dimuat.</p>'}return}
 if(ds.lessonBack!==undefined){openModal('Learning Center');return}if(ds.lessonFull!==undefined){document.querySelector('.lesson-slide')?.requestFullscreen?.();return}
 if(ds.collabPage!==undefined){state.page=+ds.collabPage;renderExperience();return}if(ds.agency!==undefined){state.agency=ds.agency||null;state.package=null;state.selected=[];state.refs=[];renderExperience();return}if(ds.package){state.package=ds.package;state.selected=[];state.refs=[];renderExperience();return}if(ds.selectCreator){state.selected??=[];state.selected=state.selected.includes(ds.selectCreator)?state.selected.filter(x=>x!==ds.selectCreator):[...state.selected,ds.selectCreator];renderExperience();return}if(ds.flowStep!==undefined){state.step=+ds.flowStep;renderExperience();return}if(ds.flowNext!==undefined){state.step=(state.step||0)+1;renderExperience();return}if(ds.flowBack!==undefined){state.step--;renderExperience();return}if(ds.group){state.group=ds.group;state.filter='all';state.videoPage=0;renderExperience();return}if(ds.filter){state.filter=ds.filter;state.videoPage=0;renderExperience();return}if(ds.ref){state.refs??=[];state.refs=state.refs.includes(ds.ref)?state.refs.filter(x=>x!==ds.ref):[...state.refs,ds.ref];renderExperience();return}if(ds.videoPage!==undefined){state.videoPage=+ds.videoPage;renderExperience();return}if(ds.market){state.market=ds.market;renderExperience();return}if(ds.report){state.report=ds.report;renderExperience();return}if(ds.demoSubmit!==undefined){let photo=document.querySelector('[data-photo]'),brief=document.querySelector('[data-symphony-brief]').value.trim();if(!photo.checked||!brief){alert('Pilih foto produk dan isi brief terlebih dahulu.');return}state.symphonyBrief=brief;state.sent=true;renderExperience();return}if(ds.demoApprove!==undefined){state.approved=true;renderExperience();return}if(ds.demoReset!==undefined){state.sent=false;state.approved=false;state.playing=false;renderExperience();return}if(ds.demoPlay!==undefined||ds.assistPlay!==undefined){state.playing=!state.playing;renderExperience();return}if(ds.assistReset!==undefined){state.playing=false;renderExperience();return}
},true);
document.addEventListener('change',e=>{let d=e.target.dataset;if(d.collab){state[d.collab]=+e.target.value;state.page=0;renderExperience()}if(d.goalToggle){state.goals??={};state.goals[d.goalToggle]=e.target.checked?({videos:2,views:10000,gmv:1000000})[d.goalToggle]:undefined;state.page=0;renderExperience()}if(d.goal){state.goals[d.goal]=+e.target.value;state.page=0;renderExperience()}if(d.creativeBudget!==undefined){state.budget=+e.target.value;state.selected=[];state.refs=[];renderExperience()}if(d.originalSize!==undefined)document.querySelector('.lesson-slide').classList.toggle('original-size',e.target.checked)});
document.addEventListener('input',e=>{if(e.target.hasAttribute('data-brief'))state.brief=e.target.value});
document.addEventListener('submit',e=>{if(e.target.id==='auth-login'){e.preventDefault();e.target.querySelector('.auth-notice').textContent='Login belum terhubung. Tidak ada data yang dikirim atau disimpan.'}if(e.target.id==='reg-code'){e.preventDefault();state.regStep=2;renderAuth()}if(e.target.id==='reg-shop'){e.preventDefault();state.regStep=3;renderAuth()}if(e.target.id==='reg-account'){e.preventDefault();let pass=[...e.target.querySelectorAll('input[type=password]')];e.target.querySelector('.auth-notice').textContent=pass[0].value!==pass[1].value?'Konfirmasi kata sandi tidak cocok.':'Pendaftaran belum terhubung. Tidak ada data yang dikirim atau disimpan.'}});

market=function(){let tab=state.market||'Audience Funnel';let data={'Audience Funnel':'<div class="stat-grid"><div><h3>Brand contoh</h3><p>Awareness 84.000 · 80,8%</p><p>Consideration 16.000 · 15,4%</p><p>Conversion 4.000 · 3,8%</p></div><div><h3>Benchmark contoh</h3><p>Awareness 240.000 · 75,9%</p><p>Consideration 60.000 · 19,0%</p><p>Conversion 16.000 · 5,1%</p></div></div>','Contribution Analysis':'<p>Kontribusi channel terhadap audiens ACC</p><div class="stat-grid"><div><small>Organik</small><strong>29.000</strong></div><div><small>Berbayar</small><strong>75.000</strong></div></div><div class="graph"><svg viewBox="0 0 400 100" preserveAspectRatio="none"><polyline points="0,85 65,70 130,77 195,65 260,60 325,54 400,49" fill="none" stroke="#be9ff6" stroke-width="3"/><polyline points="0,70 65,56 130,64 195,47 260,37 325,30 400,18" fill="none" stroke="#79d9e8" stroke-width="3"/></svg></div><p>Organik dan berbayar adalah kelompok terpisah pada data contoh ini.</p>','Audience Profile':'<div class="stat-grid"><div><h3>Lokasi</h3><p>Jakarta · 40% · 41.600</p><p>Surabaya · 35% · 36.400</p><p>Bandung · 25% · 26.000</p></div><div><h3>Gender dan umur</h3><p>Perempuan · 18–24 · 35% · 36.400</p><p>Perempuan · 25–34 · 30% · 31.200</p><p>Laki-laki · 18–34 · 35% · 36.400</p></div><div><h3>Minat</h3><p>Gaya hidup · 45% · 46.800</p><p>Belanja · 35% · 36.400</p><p>Teknologi · 20% · 20.800</p></div><div><h3>Sistem operasi</h3><p>Android · 75% · 78.000</p><p>iOS · 25% · 26.000</p></div></div>','Audience Transition':`<div class="chips"><button class="action ${state.transition!=='Tabel'?'active':''}" data-transition="Sankey">Sankey</button><button class="action ${state.transition==='Tabel'?'active':''}" data-transition="Tabel">Tabel</button></div>${state.transition==='Tabel'?'<table><thead><tr><th>Dari</th><th>Ke</th><th>Audiens</th></tr></thead><tbody><tr><td>Awareness</td><td>Awareness</td><td>67.200</td></tr><tr><td>Awareness</td><td>Consideration</td><td>15.120</td></tr><tr><td>Awareness</td><td>Conversion</td><td>1.680</td></tr><tr><td>Consideration</td><td>Consideration</td><td>13.600</td></tr><tr><td>Consideration</td><td>Conversion</td><td>2.400</td></tr><tr><td>Conversion</td><td>Conversion</td><td>4.000</td></tr></tbody></table>':'<div class="graph"><svg viewBox="0 0 400 100"><path d="M20 20 C150 20 250 20 380 20 M20 20 C150 20 250 50 380 50 M20 50 C150 50 250 75 380 75 M20 75 C150 75 250 75 380 75" fill="none" stroke="#79d9e8" stroke-width="6"/></svg></div><p>Awareness 84.000 → 67.200 · Consideration 16.000 → 28.720 · Conversion 4.000 → 8.080</p>'}<p>Jumlah audiens dipertahankan di setiap aliran contoh. Pergerakan bukan jaminan konversi.</p>`};return `<p>Brand mendapat insight pasar serta konsultasi untuk membantu memahami dan memanfaatkannya.</p>${chip(['Baca funnel','Temukan channel','Alokasikan budget'])}${card('DEMO · MARKET SCOPE',`<div class="chips">${Object.keys(data).map(x=>`<button class="action ${tab===x?'active':''}" data-market="${x}">${x}</button>`).join('')}</div>${data[tab]}`)}`};
document.addEventListener('click',e=>{let b=e.target.closest('[data-transition]');if(b){state.transition=b.dataset.transition;renderExperience()}},true);
